  const hhv = [['xxxxxxxxxxxxxxxx', 'todas as semicolcheias'], ['x.xxx.xxx.xxx.xx', 'pula a 2ª semicolcheia de cada tempo'], ['xx.xxx.xxx.xxx.x', 'pula a 3ª semicolcheia de cada tempo'], ['xxx.xxx.xxx.xxx.', 'pula a última de cada tempo'], ['axxxaxxxaxxxaxxx', 'acento em cada tempo'], ['x.x.xxxxx.x.xxxx', 'colcheias e semicolcheias misturadas'], ['xxxxxxxxxxxxxxxo', 'chimbal aberto no "a" do 4'], ['x.x.x.x.xxxxxxxx', 'colcheias e depois semicolcheias']];
